import profilepicture from "../utils/portfolio_image2.jpg";
function AboutMePage(): JSX.Element {
  return (
    <section className='items-center p-4 grid md:grid-cols-2'>
      <img
        className='my-2 py-2 rounded-full mx-auto'
        width={200}
        height={200}
        src={profilepicture}
        alt='Developer photo'
      />

      <div className='w-10/12 mx-auto md:w-full text-center'>
        <p className='text-slate-900 dark:text-slate-300 mx-4 text-lg font-bold px-2'>
          Paulius Jodka
        </p>
        <p className='text-slate-900 dark:text-slate-300 mx-4 text-md'>
          In 2023, I graduated with a bachelor's degree in computer science from
          Kaunas University of Technology. At the same time, I went deep into
          in-game script development using Vue and React frameworks as well as
          Lua.
        </p>
      </div>
    </section>
  );
}
export default AboutMePage;
